// src/respondent/respondent.controller.large.ts
// Large controller fixture: 22 public methods, delegation + transformation,
// similar-name pairs, fire-and-forget async, catch-fallback, an indirectly
// called public method, and an easy-to-miss security-critical verifier.

export interface RespondentEntity {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  status: 'active' | 'paused' | 'banned' | 'deleted';
  score: number;
  createdAt: string;
  profileSyncedAt: string | null;
}

export interface RespondentDto {
  id: string;
  email: string;
  displayName: string;
  status: string;
  score: number;
}

export interface WebhookEvent {
  type: 'respondent.updated' | 'respondent.deleted' | 'profile.synced';
  respondentId: string;
  payload: Record<string, unknown>;
}

interface RespondentService {
  create(body: unknown): Promise<RespondentEntity>;
  findOne(id: string): Promise<RespondentEntity | null>;
  findByEmail(email: string): Promise<RespondentEntity | null>;
  update(id: string, body: unknown): Promise<RespondentEntity>;
  setStatus(id: string, status: string): Promise<RespondentEntity>;
  remove(id: string): Promise<void>;
  hardRemove(id: string): Promise<void>;
  restore(id: string): Promise<RespondentEntity>;
  list(offset: number, limit: number): Promise<RespondentEntity[]>;
  search(query: string): Promise<RespondentEntity[]>;
  merge(primaryId: string, duplicateIds: string[]): Promise<RespondentEntity>;
  anonymizeFields(id: string): Promise<void>;
}

interface ProfileSyncService {
  sync(id: string): Promise<{ syncedAt: string }>;
}

interface AuditService {
  record(action: string, subjectId: string, detail?: unknown): Promise<void>;
  trail(subjectId: string): Promise<Array<{ action: string; at: string }>>;
}

interface SignatureService {
  hmac(payload: string): string;
}

const VALID_STATUSES = ['active', 'paused', 'banned'];
const MAX_PAGE_SIZE = 100;

export class RespondentController {
  constructor(
    private readonly service: RespondentService,
    private readonly profiles: ProfileSyncService,
    private readonly audit: AuditService,
    private readonly signatures: SignatureService,
  ) {}

  async create(body: unknown): Promise<RespondentDto> {
    const entity = await this.service.create(body);
    await this.audit.record('respondent.create', entity.id);
    return this.toDto(entity);
  }

  async createBulk(bodies: unknown[]): Promise<{ created: RespondentDto[]; failed: number }> {
    const created: RespondentDto[] = [];
    let failed = 0;
    for (const body of bodies) {
      try {
        created.push(this.toDto(await this.service.create(body)));
      } catch {
        failed += 1;
      }
    }
    return { created, failed };
  }

  async findOne(id: string): Promise<RespondentDto> {
    const entity = await this.service.findOne(id);
    if (!entity) {
      throw new Error(`Respondent ${id} not found`);
    }
    return this.toDto(entity);
  }

  async findByEmail(email: string): Promise<RespondentDto | null> {
    const entity = await this.service.findByEmail(this.normalizeEmail(email));
    return entity ? this.toDto(entity) : null;
  }

  async update(id: string, body: unknown): Promise<RespondentDto> {
    const entity = await this.service.update(id, body);
    await this.audit.record('respondent.update', id);
    return this.toDto(entity);
  }

  async patchStatus(id: string, status: string): Promise<RespondentDto> {
    if (!VALID_STATUSES.includes(status)) {
      throw new Error(`Invalid status: ${status}`);
    }
    const entity = await this.service.setStatus(id, status);
    return this.toDto(entity);
  }

  async remove(id: string, hard = false): Promise<{ removed: true; mode: string }> {
    if (hard) {
      await this.service.hardRemove(id);
      await this.audit.record('respondent.hard-remove', id);
      return { removed: true, mode: 'hard' };
    }
    await this.service.remove(id);
    return { removed: true, mode: 'soft' };
  }

  async restore(id: string): Promise<RespondentDto> {
    const entity = await this.service.restore(id);
    return this.toDto(entity);
  }

  async summary(id: string): Promise<{ id: string; displayName: string; tier: string }> {
    const dto = await this.findOne(id);
    return { id: dto.id, displayName: dto.displayName, tier: this.tierOf(dto.score) };
  }

  async summarize(ids: string[]): Promise<{ total: number; byTier: Record<string, number> }> {
    const byTier: Record<string, number> = {};
    for (const id of ids) {
      const s = await this.summary(id);
      byTier[s.tier] = (byTier[s.tier] ?? 0) + 1;
    }
    return { total: ids.length, byTier };
  }

  async listRespondents(page: number, pageSize: number): Promise<RespondentDto[]> {
    if (page < 1) {
      throw new Error('page must be >= 1');
    }
    const limit = Math.min(pageSize, MAX_PAGE_SIZE);
    const entities = await this.service.list((page - 1) * limit, limit);
    return entities.map((e) => this.toDto(e));
  }

  async searchRespondents(query: string): Promise<RespondentDto[]> {
    if (!query.trim()) {
      return [];
    }
    const entities = await this.service.search(query.trim());
    return entities.map((e) => this.toDto(e));
  }

  async *exportRespondents(statusFilter?: string): AsyncGenerator<string> {
    yield 'id,email,displayName,status,score\n';
    let page = 1;
    for (;;) {
      const batch = await this.service.list((page - 1) * MAX_PAGE_SIZE, MAX_PAGE_SIZE);
      if (batch.length === 0) {
        return;
      }
      for (const entity of batch) {
        if (statusFilter && entity.status !== statusFilter) {
          continue;
        }
        yield this.buildExportRow(entity);
      }
      page += 1;
    }
  }

  // Public, but reached only through exportRespondents in-process — an
  // external CSV consumer contract, easy to miss in an inventory.
  buildExportRow(entity: RespondentEntity): string {
    const dto = this.toDto(entity);
    const escaped = dto.displayName.includes(',')
      ? `"${dto.displayName.replace(/"/g, '""')}"`
      : dto.displayName;
    return `${dto.id},${dto.email},${escaped},${dto.status},${dto.score}\n`;
  }

  async handleWebhook(event: WebhookEvent, signature: string): Promise<{ accepted: boolean }> {
    if (!this.verifyWebhookSignature(JSON.stringify(event), signature)) {
      throw new Error('Invalid webhook signature');
    }
    switch (event.type) {
      case 'respondent.updated':
        await this.service.update(event.respondentId, event.payload);
        break;
      case 'respondent.deleted':
        await this.service.remove(event.respondentId);
        break;
      case 'profile.synced':
        break;
      default:
        return { accepted: false };
    }
    // fire-and-forget: webhook latency must not depend on audit persistence
    void this.audit.record('webhook', event.respondentId, event.type);
    return { accepted: true };
  }

  verifyWebhookSignature(payload: string, signature: string): boolean {
    if (!signature) {
      return false;
    }
    return this.signatures.hmac(payload) === signature;
  }

  async syncProfile(id: string): Promise<{ synced: boolean; syncedAt: string | null }> {
    try {
      const result = await this.profiles.sync(id);
      return { synced: true, syncedAt: result.syncedAt };
    } catch {
      // degrade instead of failing the caller — sync is retried by a cron
      return { synced: false, syncedAt: null };
    }
  }

  async syncProfiles(ids: string[]): Promise<{ synced: number; failed: string[] }> {
    let synced = 0;
    const failed: string[] = [];
    for (const id of ids) {
      const result = await this.syncProfile(id);
      if (result.synced) {
        synced += 1;
      } else {
        failed.push(id);
      }
    }
    return { synced, failed };
  }

  async anonymize(id: string): Promise<{ anonymized: true }> {
    const entity = await this.service.findOne(id);
    if (!entity) {
      throw new Error(`Respondent ${id} not found`);
    }
    await this.service.anonymizeFields(id);
    await this.audit.record('respondent.anonymize', id, { gdpr: true });
    return { anonymized: true };
  }

  async mergeDuplicates(primaryId: string, duplicateIds: string[]): Promise<RespondentDto> {
    if (duplicateIds.length === 0) {
      throw new Error('No duplicates to merge');
    }
    if (duplicateIds.includes(primaryId)) {
      throw new Error('Primary id cannot appear in duplicates');
    }
    const merged = await this.service.merge(primaryId, duplicateIds);
    await this.audit.record('respondent.merge', primaryId, { count: duplicateIds.length });
    return this.toDto(merged);
  }

  async getAuditTrail(id: string): Promise<Array<{ action: string; at: string }>> {
    const rows = await this.audit.trail(id);
    return rows.map((r) => ({ action: r.action, at: new Date(r.at).toISOString() }));
  }

  healthcheck(): { ok: true } {
    return { ok: true };
  }

  private normalizeEmail(email: string): string {
    return email.trim().toLowerCase();
  }

  private tierOf(score: number): string {
    if (score >= 80) {
      return 'gold';
    }
    if (score >= 50) {
      return 'silver';
    }
    return 'bronze';
  }

  private toDto(entity: RespondentEntity): RespondentDto {
    return {
      id: entity.id,
      email: entity.email,
      displayName: `${entity.firstName} ${entity.lastName}`.trim(),
      status: entity.status,
      score: entity.score,
    };
  }
}
